// The wire code is COMMITTED at src/gen/easybus.v1.rs and generated by `make gen` (buf).
//
// This script does not generate, and that is deliberate. It used to: prost_build wrote the
// file on every `cargo build`. Two problems with that —
//
//   - a build rewrote a tracked file, so a stale checkout repaired itself silently instead of
//     showing up as a diff;
//   - prost_build drops the proto's comments, so the generated structs carried no docs.
//
// Generating through buf (the same driver the Go, TypeScript and Python SDKs use) fixes both:
// the output is committed and reviewable, and the comments survive as `///` docs.
//
// Building now only checks the file is there, so a missing one fails with a clear message
// instead of an "include!" error pointing at a generated path.
use std::path::Path;

fn main() {
    let generated = Path::new("src/gen/easybus.v1.rs");
    if !generated.is_file() {
        println!(
            "cargo:warning={} is missing; run `make gen` and commit the result",
            generated.display()
        );
    }
    println!("cargo:rerun-if-changed=proto/easybus/v1/protocol.proto");
    println!("cargo:rerun-if-changed=src/gen/easybus.v1.rs");
}
